param([Parameter(Mandatory=$true)][ValidateSet('C02','C11')][string]$Job,[Parameter(Mandatory=$true)][int]$Round,[Parameter(Mandatory=$true)][ValidateSet('A','B')][string]$Group)
$ErrorActionPreference='Stop';$root='D:\musicclaude\_dl_latest_zip_work';Set-Location -LiteralPath $root;$env:CODEX_HOME=if($Group -eq 'A'){Join-Path $env:USERPROFILE '.codex'}else{Join-Path $env:USERPROFILE '.codex-web'};$log=Join-Path $root ("stage2_{0}_r{1:d2}_manual_retry.log"-f $Job,$Round);"START $Job r$Round group=$Group profile=$env:CODEX_HOME $(Get-Date -Format o)"|Out-File -LiteralPath $log -Encoding utf8;& python scripts\run_repeated_trials.py --phase trial --round-start $Round --round-end $Round --execute --only-job $Job --retry-confirmed-pre-submit *> (Join-Path $root ("stage2_{0}_r{1:d2}_manual_retry_runner.log"-f $Job,$Round));$code=$LASTEXITCODE;"END exit=$code $(Get-Date -Format o)"|Out-File -Append -LiteralPath $log -Encoding utf8
